"use client";
import * as React from "react";
import { cn } from "../lib/cn";
import { CountUp } from "../lib/count-up";

export interface ProgressProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Waarde tussen 0 en `max`. Laat weg voor een onbepaalde balk. */
  value?: number;
  max?: number;
  tone?: "accent" | "green" | "amber" | "red" | "blue";
  size?: "sm" | "md" | "lg";
  /** Label boven de balk. */
  label?: React.ReactNode;
  /** Toont het percentage rechtsboven. */
  showValue?: boolean;
}

/** Progress — voortgangsbalk, bepaald of onbepaald. */
export const Progress = React.forwardRef<HTMLDivElement, ProgressProps>(function Progress(
  { value, max = 100, tone = "accent", size = "md", label, showValue, className, ...rest },
  ref
) {
  const indeterminate = value === undefined || value === null;
  const percent = indeterminate ? 0 : Math.min(100, Math.max(0, (value / max) * 100));

  return (
    <div ref={ref} className={cn("lui-progress-wrap", className)} {...rest}>
      {(label || showValue) && (
        <div className="lui-progress-head">
          {label && <span className="lui-progress-label">{label}</span>}
          {showValue && !indeterminate && (
            <span className="lui-progress-value">
              <CountUp value={Math.round(percent)} />%
            </span>
          )}
        </div>
      )}
      <div
        className={cn("lui-progress", `lui-progress-${size}`, `lui-progress-${tone}`)}
        role="progressbar"
        aria-valuemin={0}
        aria-valuemax={max}
        aria-valuenow={indeterminate ? undefined : value}
      >
        <div
          className={cn("lui-progress-bar", indeterminate && "lui-progress-bar-indeterminate")}
          style={indeterminate ? undefined : { width: `${percent}%` }}
        />
      </div>
    </div>
  );
});

export interface ProgressCircleProps extends React.HTMLAttributes<HTMLDivElement> {
  value?: number;
  max?: number;
  size?: number;
  thickness?: number;
  tone?: "accent" | "green" | "amber" | "red" | "blue";
  /** Toont het percentage in het midden. */
  showValue?: boolean;
}

/** ProgressCircle — ronde voortgangsindicator. */
export const ProgressCircle = React.forwardRef<HTMLDivElement, ProgressCircleProps>(
  function ProgressCircle(
    { value = 0, max = 100, size = 56, thickness = 5, tone = "accent", showValue, className, ...rest },
    ref
  ) {
    const percent = Math.min(100, Math.max(0, (value / max) * 100));
    const radius = (size - thickness) / 2;
    const circumference = 2 * Math.PI * radius;

    return (
      <div
        ref={ref}
        className={cn("lui-progress-circle", `lui-progress-${tone}`, className)}
        style={{ width: size, height: size }}
        role="progressbar"
        aria-valuemin={0}
        aria-valuemax={max}
        aria-valuenow={value}
        {...rest}
      >
        <svg width={size} height={size}>
          <circle
            className="lui-progress-circle-track"
            cx={size / 2}
            cy={size / 2}
            r={radius}
            strokeWidth={thickness}
            fill="none"
          />
          <circle
            className="lui-progress-circle-bar"
            cx={size / 2}
            cy={size / 2}
            r={radius}
            strokeWidth={thickness}
            fill="none"
            strokeLinecap="round"
            strokeDasharray={circumference}
            strokeDashoffset={circumference - (percent / 100) * circumference}
            style={{ "--lui-circ": circumference } as React.CSSProperties}
            transform={`rotate(-90 ${size / 2} ${size / 2})`}
          />
        </svg>
        {showValue && (
          <span className="lui-progress-circle-value">
            <CountUp value={Math.round(percent)} />%
          </span>
        )}
      </div>
    );
  }
);

/* ============================ Progress ============================ */
.lui-progress-wrap { --lui-progress-color: var(--accent); display: flex; flex-direction: column; gap: 7px; width: 100%; }
.lui-progress-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.lui-progress-label { font-size: 13px; font-weight: 550; color: var(--text-2); }
.lui-progress-value { font-size: var(--fs-sm); font-weight: 650; color: var(--text); font-family: var(--mono); }

.lui-progress {
  --lui-progress-color: var(--accent);
  position: relative; width: 100%; height: 8px; overflow: hidden;
  background: var(--surface-3); border-radius: var(--r-full);
}
.lui-progress-sm { height: 5px; }
.lui-progress-lg { height: 12px; }

.lui-progress-accent { --lui-progress-color: var(--accent); }
.lui-progress-green { --lui-progress-color: var(--green); }
.lui-progress-amber { --lui-progress-color: var(--amber); }
.lui-progress-red { --lui-progress-color: var(--red); }
.lui-progress-blue { --lui-progress-color: var(--blue); }

.lui-progress-bar {
  height: 100%; border-radius: inherit;
  background: var(--lui-progress-color);
  transition: width .45s var(--ease-out);
}
.lui-progress-bar-indeterminate {
  width: 38%; position: absolute; left: 0;
  animation: lui-progress-slide 1.15s var(--ease) infinite;
}
@keyframes lui-progress-slide {
  0% { transform: translateX(-100%); }
  100% { transform: translateX(365%); }
}

/* ---------- Circle ---------- */
.lui-progress-circle { position: relative; display: inline-grid; place-items: center; }
.lui-progress-circle svg { position: absolute; inset: 0; }
.lui-progress-circle-track { stroke: var(--surface-3); }
.lui-progress-circle-bar {
  stroke: var(--lui-progress-color, var(--accent));
  transition: stroke-dashoffset .5s var(--ease-out);
}
.lui-progress-circle-value {
  font-size: var(--fs-sm); font-weight: 700; color: var(--text); font-family: var(--mono);
}

/* ---------- Mount: balk en ring vullen zich vanaf nul ---------- */
.lui-progress-bar:not(.lui-progress-bar-indeterminate) {
  transform-origin: left; animation: lui-fill-x .9s var(--ease-out) both;
  position: relative; overflow: hidden;
}
[dir="rtl"] .lui-progress-bar:not(.lui-progress-bar-indeterminate) { transform-origin: right; }
/* Zachte glans die af en toe over de balk loopt. */
.lui-progress-bar:not(.lui-progress-bar-indeterminate)::after {
  content: ""; position: absolute; inset: 0;
  background: linear-gradient(100deg, transparent 30%, rgb(255 255 255 / .35) 50%, transparent 70%);
  transform: translateX(-100%);
  animation: lui-progress-sheen 2.6s var(--ease) 1s infinite;
}
@keyframes lui-progress-sheen { 0% { transform: translateX(-100%); } 45%, 100% { transform: translateX(100%); } }
.lui-progress-circle-bar { animation: lui-progress-ring 1s var(--ease-out) both; }
@keyframes lui-progress-ring { from { stroke-dashoffset: var(--lui-circ); } }
@media (prefers-reduced-motion: reduce) {
  .lui-progress-bar::after { display: none; }
}

"use client";
import * as React from "react";

/**
 * Laat een getal optellen van 0 (of de vorige waarde) naar `target` zodra het
 * element in beeld komt. Respecteert prefers-reduced-motion: dan staat de
 * eindwaarde er meteen.
 */
export function useCountUp(
  target: number,
  options: { duration?: number; ref?: React.RefObject<Element | null>; enabled?: boolean } = {}
): number {
  const { duration = 900, ref, enabled = true } = options;
  const [waarde, setWaarde] = React.useState(enabled ? 0 : target);
  const vorige = React.useRef(0);
  const [inBeeld, setInBeeld] = React.useState(!ref);

  React.useEffect(() => {
    if (!ref?.current || inBeeld) return;
    if (typeof IntersectionObserver === "undefined") {
      setInBeeld(true);
      return;
    }
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries.some((entry) => entry.isIntersecting)) {
          setInBeeld(true);
          observer.disconnect();
        }
      },
      { threshold: 0.2 }
    );
    observer.observe(ref.current);
    return () => observer.disconnect();
  }, [ref, inBeeld]);

  React.useEffect(() => {
    if (!enabled || !inBeeld) return;
    const rustig =
      typeof window !== "undefined" && window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
    if (rustig || !Number.isFinite(target)) {
      vorige.current = target;
      setWaarde(target);
      return;
    }
    const van = vorige.current;
    const start = performance.now();
    let frame = 0;
    const stap = (nu: number) => {
      const t = Math.min(1, (nu - start) / duration);
      // easeOutExpo: snel vertrekken, zacht landen.
      const e = t === 1 ? 1 : 1 - Math.pow(2, -10 * t);
      setWaarde(van + (target - van) * e);
      if (t < 1) frame = requestAnimationFrame(stap);
      else vorige.current = target;
    };
    frame = requestAnimationFrame(stap);
    return () => {
      cancelAnimationFrame(frame);
      vorige.current = target;
    };
  }, [target, duration, enabled, inBeeld]);

  return enabled ? waarde : target;
}

interface Ontleed {
  voor: string;
  getal: number;
  na: string;
  decimalen: number;
  duizend: string;
  komma: string;
}

/** Haalt het eerste getal uit een tekst als "€ 12.480" of "98,4%" en onthoudt de opmaak. */
export function parseNumberText(tekst: string): Ontleed | null {
  const match = tekst.match(/\d+(?:[.,   ]\d+)*/);
  if (!match || match.index === undefined) return null;
  const ruw = match[0];
  const voor = tekst.slice(0, match.index);
  const na = tekst.slice(match.index + ruw.length);
  const minteken = /[-−]\s*$/.test(voor);

  const scheiders = ruw.match(/[.,   ]/g) ?? [];
  let komma = "";
  let duizend = "";
  if (scheiders.length > 0) {
    const laatste = scheiders[scheiders.length - 1] ?? "";
    const naLaatste = ruw.slice(ruw.lastIndexOf(laatste) + 1);
    const soorten = new Set(scheiders);
    if (soorten.size > 1) {
      komma = laatste;
      duizend = scheiders[0] ?? "";
    } else if (scheiders.length === 1 && naLaatste.length !== 3 && (laatste === "." || laatste === ",")) {
      komma = laatste;
    } else {
      duizend = laatste;
    }
  }
  const [heel, deel = ""] = komma ? [ruw.slice(0, ruw.lastIndexOf(komma)), ruw.slice(ruw.lastIndexOf(komma) + 1)] : [ruw, ""];
  const cijfers = heel.replace(/[^\d]/g, "");
  const getal = Number(`${cijfers}.${deel || "0"}`);
  if (!Number.isFinite(getal)) return null;
  return {
    voor: minteken ? voor.replace(/[-−]\s*$/, "") : voor,
    getal: minteken ? -getal : getal,
    na,
    decimalen: deel.length,
    duizend,
    komma: komma || ",",
  };
}

function schrijf(getal: number, o: Ontleed): string {
  const negatief = getal < 0;
  const [heel, deel] = Math.abs(getal).toFixed(o.decimalen).split(".");
  const metGroepen = o.duizend ? heel.replace(/\B(?=(\d{3})+(?!\d))/g, o.duizend) : heel;
  return `${o.voor}${negatief ? "−" : ""}${metGroepen}${deel ? o.komma + deel : ""}${o.na}`;
}

export interface CountUpProps {
  /** Getal of tekst met een getal erin; andere inhoud wordt gewoon getoond. */
  value: React.ReactNode;
  duration?: number;
  /** Zet op false om meteen de eindwaarde te tonen. */
  enabled?: boolean;
  className?: string;
}

/** CountUp — telt het getal in `value` op wanneer het in beeld komt, met behoud van opmaak. */
export function CountUp({ value, duration, enabled = true, className }: CountUpProps) {
  const ref = React.useRef<HTMLSpanElement>(null);
  const ontleed = React.useMemo(() => {
    if (typeof value === "number") {
      const tekst = String(value);
      const decimalen = tekst.includes(".") ? tekst.split(".")[1].length : 0;
      return { voor: "", getal: value, na: "", decimalen, duizend: "", komma: "." } satisfies Ontleed;
    }
    return typeof value === "string" ? parseNumberText(value) : null;
  }, [value]);

  const huidig = useCountUp(ontleed?.getal ?? 0, { duration, ref, enabled: enabled && ontleed !== null });

  if (!ontleed) return <>{value}</>;
  return (
    <span ref={ref} className={className} style={{ fontVariantNumeric: "tabular-nums" }}>
      {/* Screenreaders krijgen meteen de echte waarde. */}
      <span aria-hidden="true">{schrijf(huidig, ontleed)}</span>
      <span className="lui-sr-only">{typeof value === "number" ? String(value) : value}</span>
    </span>
  );
}
